"""Incremental camera-guided controller for the single live episode.
Only Robot spec, observations, and joint submissions are used.
All submitted targets are also appended to actions.jsonl for replay.
"""
import json, pathlib, argparse, numpy as np
from scipy.spatial.transform import Rotation as R
from rcb_client import Robot
from kin import ik, fk
OUT=pathlib.Path('/app/output')
DOWN=np.diag([1.,-1.,-1.])
class Controller:
 def __init__(self):
  self.r=Robot(); self.obs=self.r.get_obs(video='none'); self.s=np.array(self.obs.meta['proprio']['now'])
 def record(self,res,name):
  res.save(str(OUT/name)); self.obs=res;self.s=np.array(res.meta['proprio']['now']); print(name, 'steps',res.meta['control_steps'],'done',res.done,res.meta['reason'],'tcp',self.s[16:23],'fingers',self.s[14:16],flush=True)
 def joints(self,q,f=.04,seconds=2,name='move'):
  start=self.s[:7]; n=max(1,round(seconds/.1)); A=np.c_[np.linspace(start,q,n),np.full((n,2),f)]
  with open(OUT/'actions.jsonl','a') as log: log.write(json.dumps(dict(actions=A.tolist(),dt=.1,name=name))+'\n')
  res=self.r.submit('joint_position',A,dt=.1,cameras=None,video='none',include_depth=True,note=name);self.record(res,name);return res
 def move(self,p,rot=DOWN,f=.04,seconds=2,name='move'):
  return self.joints(ik(np.array(p),rot,self.s[:7]),f,seconds,name)
 def grip(self,f,seconds=1,name='grip'): return self.joints(self.s[:7],f,seconds,name)
if __name__=='__main__':
 a=argparse.ArgumentParser(); a.add_argument('command',choices=['observe','move','grip']);a.add_argument('--p',nargs=3,type=float);a.add_argument('--rot',nargs=3,type=float);a.add_argument('--f',type=float,default=.04);a.add_argument('--seconds',type=float,default=2);a.add_argument('--name',default='latest');args=a.parse_args(); c=Controller()
 if args.command=='observe':c.record(c.r.get_obs(include_depth=True,video='none'),args.name)
 elif args.command=='grip':c.grip(args.f,args.seconds,args.name)
 else:c.move(args.p,R.from_euler('xyz',args.rot,degrees=True).as_matrix() if args.rot else DOWN,args.f,args.seconds,args.name)
